CREATE TABLE IF NOT EXISTS player_profiles (player_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, level INTEGER NOT NULL DEFAULT 1, xp INTEGER NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lobbies (lobby_id TEXT PRIMARY KEY, host_name TEXT NOT NULL, mode TEXT NOT NULL, map_id TEXT NOT NULL, max_players INTEGER NOT NULL DEFAULT 10, current_players INTEGER NOT NULL DEFAULT 1, is_private INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
